import { useReducer } from 'react';

type State<T> = { past: T[]; present: T; future: T[] };
type Action<T> = { type: 'set'; value: T } | { type: 'undo' } | { type: 'redo' };

function reducer<T>(state: State<T>, action: Action<T>): State<T> {
  switch (action.type) {
    case 'set':
      return { past: [...state.past, state.present], present: action.value, future: [] };
    case 'undo':
      if (state.past.length === 0) return state;
      return {
        past: state.past.slice(0, -1),
        present: state.past[state.past.length - 1],
        future: [state.present, ...state.future],
      };
    case 'redo':
      if (state.future.length === 0) return state;
      return {
        past: [...state.past, state.present],
        present: state.future[0],
        future: state.future.slice(1),
      };
    default:
      return state;
  }
}

export function useReducerHistory<T>(initial: T) {
  const [state, dispatch] = useReducer(reducer as (s: State<T>, a: Action<T>) => State<T>, {
    past: [],
    present: initial,
    future: [],
  });

  return {
    value: state.present,
    set: (value: T) => dispatch({ type: 'set', value }),
    undo: () => dispatch({ type: 'undo' }),
    redo: () => dispatch({ type: 'redo' }),
    canUndo: state.past.length > 0,
    canRedo: state.future.length > 0,
  };
}
